def _auto_disable_accelerated_2d_canvas(
        versions: version.WebEngineVersions,
        _namespace: argparse.Namespace,
        _special_flags: Sequence[str],
) -> str:
    """Enable the canvas workaround for Qt 6 with Chromium older than 111."""
    chromium_major = versions.chromium_major
    if machinery.IS_QT6 and chromium_major and chromium_major < 111:
        return 'always'
    return 'never'


